SourceCode.Declaration:
public class METTMSEngineHeaderTransferOrderContract extends METTMSEngineHeaderContract
{
    METInventTransferTableExt inventTransferTableExt;
    CustAccount custAccount;

}

Method.Source:
/// <summary>
///
/// </summary>
/// <returns></returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = inventTransferTableExt.StagingLane;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public Common getExtensionTable()
{
    Common ret = inventTransferTableExt;

    return ret;
}

/// <summary>
/// Gets the customer account of the order
/// </summary>
/// <returns>Customer account number</returns>
public CustAccount getCustomerAccount()
{
    if(custAccount != '')
    {
        custAccount = METInventLocation::findByInventLocationId(sourceRecord.InventLocationTo).InternalCustomer;
    }

    return custAccount;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METTMSShipmentID getShipmentID()
{
    if(!shipmentId)
    {
        str shippingDateStr = date2Str
        (sourceRecord.getShipDate(),
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

        shipmentId = strFmt("@MET:ShipmentStrFmt",
        sourceRecord.InventLocationFrom,
        sourceRecord.InventLocationTo,
        inventTransferTableExt.Route,
        shippingDateStr);
    }

    return super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METRouteStopNum getRouteStop()
{
    METRouteStopNum ret = inventTransferTableExt.RouteStopNum;

    return ret;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean isOrderExcluded()
{
    boolean ret = false;

    return ret;
}

/// <summary>
/// Gets the order split group from source document
/// </summary>
/// <returns>Order split group id</returns>
public METOrderSplitGroup getOrderSplitGroup()
{
    return inventTransferTableExt.OrderSplitGroup;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = inventTransferTableExt.RouteStopIdentifier;

    return ret;
}

/// <summary>
/// Get the route identifier of the order
/// </summary>
/// <returns>Route identifier</returns>
public METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = inventTransferTableExt.RouteIdentifier;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public NoYes isInternalCrossDockOrder()
{
    NoYes ret;

    ret = inventTransferTableExt.TransferType == METCrossDockTransferType::CrossDock;

    return ret;
}

/// <summary>
/// Gets the carrier code of the order
/// </summary>
/// <returns>Carrier code</returns>
public TMSCarrierCode getCarrierCode()
{
    TMSCarrierCode ret;

    if(!carrierCode)
    {
        carrierCode = TMSInventTransferTable::find(sourceRecord.OrderId).CarrierCode;
    }

    ret = super();

    return ret;
}
